import { type Component as ParentComponent } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { Activatable, ActivatableProps } from "./activatable";

export type CheckBoxProps = {
	isChecked?: boolean;
} & ActivatableProps;

const CheckBoxComponent: ParentComponent<CheckBoxProps> = (props) => {
	return (
		<Activatable
			{...props}
			class={`flex flex-row group justify-center items-center ${props.class ?? ""}`}
			name="CheckBox"
		>
			<div
				class={`${props.isChecked ? "check-box-on" : "check-box-off"} cursor-pointer pointer-events-auto relative flex justify-center items-center size-full bg-contain`}
			/>
		</Activatable>
	);
};

export const CheckBox = ComponentRegistry.register({
	name: "CheckBox",
	createInstance: CheckBoxComponent,
	images: ["blp:base_checkbox-off", "blp:base_checkbox-off-highlight", "blp:base_checkbox-on-highlight"],
});
